expand_details.cypher:
MATCH (start:node {name: 'k8s-node1'})
CALL apoc.path.expandConfig(start, {
    sequence: 'node,hosts,pod,contains,container',
    minLevel: 0,
    maxLevel: 2,
    bfs: true
})
YIELD path
RETURN path, length(path) AS hops
ORDER BY hops;

